import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as a,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何用 Linux 命令列發電子郵件 | LCTT x X-CMD","titleTemplate":false,"description":"如何用 Linux 命令列發電子郵件 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用 Linux 命令列發電子郵件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用 Linux 命令列發電子郵件 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190614 How to send email from the Linux command line","title":"如何用 Linux 命令列發電子郵件","tag":"201906","desc":""},"relativePath":"201906/20190614 How to send email from the Linux command line.md","filePath":"[post].md"}'),c={name:"201906/20190614 How to send email from the Linux command line.md"};function h(g,s,u,k,m,b){const e=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何用-linux-命令列發電子郵件" tabindex="-1">如何用 Linux 命令列發電子郵件 <a class="header-anchor" href="#如何用-linux-命令列發電子郵件" aria-label="Permalink to “如何用 Linux 命令列發電子郵件”">​</a></h1><blockquote><p>Linux 提供了幾個可以讓你通過終端發送電子郵件的命令，下面來展示一些有趣的方法。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2017/08/email_image_blue-100732096-large.jpg" alt="Molnia/iStock"></p><p>Linux 可以用多種方式通過命令列發送電子郵件。有一些方法十分簡單，有一些相對會複雜一些，不過仍舊提供了很多有用的特性。選擇哪一種方式取決於你想要什麼 —— 向同事快速發送消息，還是向一批人羣髮帶有附件的更復雜的信息。接下來看一看幾種可行方案：</p><h3 id="mail" tabindex="-1">mail <a class="header-anchor" href="#mail" aria-label="Permalink to “mail”">​</a></h3><p>發送一條簡單消息最便捷的 Linux 命令是 <code>mail</code>。假設你需要提醒老闆你今天得早點走，你可以使用這樣的一條命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Reminder: Leaving at 4 PM today&quot; | mail -s &quot;early departure&quot; myboss</span></span></code></pre></div><p>另一種方式是從一個文件中提取出你想要發送的文本信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mail -s &quot;Reminder:Leaving early&quot; myboss &lt; reason4leaving</span></span></code></pre></div><p>在以上兩種情況中，你都可以通過 <code>-s</code> 來為郵件添加標題。</p><h3 id="sendmail" tabindex="-1">sendmail <a class="header-anchor" href="#sendmail" aria-label="Permalink to “sendmail”">​</a></h3><p>使用 <code>sendmail</code> 命令可以發送一封不包含標題的快信。（用目標收件人替換 <code>recip</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;leaving now&quot; | sendmail recip</span></span></code></pre></div><p>你可以用這條命令發送一條只有標題，沒有內容的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Subject: leaving now&quot; | sendmail recip</span></span></code></pre></div><p>你也可以用 <code>sendmail</code> 發送一條包含一條標題行的完整信息。不過使用這個方法時，你的標題行會被添加到要發送的文件中，如下例所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Subject: Requested lyrics</span></span>
<span class="line"><span>I would just like to say that, in my opinion, longer hair and other flamboyant</span></span>
<span class="line"><span>affectations of appearance are nothing more ...</span></span></code></pre></div><p>你也可以發送這樣的文件（<code>lyric</code> 文件包含標題和正文）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sendmail recip &lt; lyrics</span></span></code></pre></div><p><code>sendmain</code> 的輸出也可以很冗長。如果你感到好奇並希望查看發送系統和接收系統之間的交互，請添加 <code>-v</code> （verbose）選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sendmail -v recip@emailsite.com &lt; lyrics</span></span></code></pre></div><h3 id="mutt" tabindex="-1">mutt <a class="header-anchor" href="#mutt" aria-label="Permalink to “mutt”">​</a></h3><p><code>mutt</code> 是通過命令列發送郵件的一個很好的工具，在使用前你需要安裝它。<code>mutt</code> 的一個很方便的優勢就是它允許你在郵件中添加附件。</p><p>使用 <code>mutt</code> 發送一條快速信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Please check last night&#39;s backups&quot; | mutt -s &quot;backup check&quot; recip</span></span></code></pre></div><p>從文件中獲取內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mutt -s &quot;Agenda&quot; recip &lt; agenda</span></span></code></pre></div><p>使用 <code>-a</code> 選項在 <code>mutt</code> 中添加附件。你甚至可以添加不止一個附件 —— 如下一條命令所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mutt -s &quot;Agenda&quot; recip -a agenda -a speakers &lt; msg</span></span></code></pre></div><p>在以上的命令中，<code>msg</code> 文件包含了郵件中的正文。如果你沒有其他補充的內容，你可以這樣來代替之前的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;&quot; | mutt -s &quot;Agenda&quot; recip -a agenda -a speakers</span></span></code></pre></div><p><code>mutt</code> 另一個有用的功能是可以添加抄送（<code>-c</code>）和密送（<code>-b</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mutt -s &quot;Minutes from last meeting&quot; recip@somesite.com -c myboss &lt; mins</span></span></code></pre></div><h3 id="telnet" tabindex="-1">telnet <a class="header-anchor" href="#telnet" aria-label="Permalink to “telnet”">​</a></h3><p>如果你想深入瞭解發送電子郵件的細節，你可以使用 <code>telnet</code> 來進行電子郵件交互操作。但正如所説的那樣，你需要“學習術語”。郵件服務器期望一系列命令，其中包括自我介紹（<code>EHLO</code> 命令）、提供發件人（<code>MAIL FROM</code> 命令）、指定收件人（<code>RCPT TO</code> 命令），然後添加消息（<code>DATA</code>）並以 <code>.</code> 結束消息。並不是所有的電子郵件服務器都會響應這些請求。此方法通常僅用於故障排除。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ telnet emailsite.org 25</span></span>
<span class="line"><span>Trying 192.168.0.12...</span></span>
<span class="line"><span>Connected to emailsite.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>220 localhost ESMTP Sendmail 8.15.2/8.15.2/Debian-12; Wed, 12 Jun 2019 16:32:13 -0400; (No UCE/UBE) logging access from: mysite(OK)-mysite [192.168.0.12]</span></span>
<span class="line"><span>EHLO mysite.org                &lt;== introduce yourself</span></span>
<span class="line"><span>250-localhost Hello mysite [127.0.0.1], pleased to meet you</span></span>
<span class="line"><span>250-ENHANCEDSTATUSCODES</span></span>
<span class="line"><span>250-PIPELINING</span></span>
<span class="line"><span>250-EXPN</span></span>
<span class="line"><span>250-VERB</span></span>
<span class="line"><span>250-8BITMIME</span></span>
<span class="line"><span>250-SIZE</span></span>
<span class="line"><span>250-DSN</span></span>
<span class="line"><span>250-ETRN</span></span>
<span class="line"><span>250-AUTH DIGEST-MD5 CRAM-MD5</span></span>
<span class="line"><span>250-DELIVERBY</span></span>
<span class="line"><span>250 HELP</span></span>
<span class="line"><span>MAIL FROM: me@mysite.org       &lt;== 指定發件人</span></span>
<span class="line"><span>250 2.1.0 shs@mysite.org... Sender ok</span></span>
<span class="line"><span>RCPT TO: recip             &lt;== 指定收件人</span></span>
<span class="line"><span>250 2.1.5 recip... Recipient ok</span></span>
<span class="line"><span>DATA                   &lt;== 郵件內容開始</span></span>
<span class="line"><span>354 Enter mail, end with &quot;.&quot; on a line by itself</span></span>
<span class="line"><span>This is a test message. Please deliver it for me.</span></span>
<span class="line"><span>.                  &lt;== 內容結束</span></span>
<span class="line"><span>250 2.0.0 x5CKWDds029287 Message accepted for delivery</span></span>
<span class="line"><span>quit                   &lt;== 結束交互</span></span></code></pre></div><h3 id="向多個收件人發送電子郵件" tabindex="-1">向多個收件人發送電子郵件 <a class="header-anchor" href="#向多個收件人發送電子郵件" aria-label="Permalink to “向多個收件人發送電子郵件”">​</a></h3><p>如果你希望通過 Linux 命令列向一大組收件人發送電子郵件，你可以使用一個循環來幫助你完成任務，如下面應用在 <code>mutt</code> 中的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for recip in \`cat recips\`</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    mutt -s &quot;Minutes from May meeting&quot; $recip &lt; May_minutes</span></span>
<span class="line"><span>done</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>有很多方法可以從 Linux 命令列發送電子郵件。有些工具提供了相當多的選項。</p><hr>`,42)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://www.networkworld.com/article/3402027/how-to-send-email-from-the-linux-command-line.html"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3402027/how-to-send-email-from-the-linux-command-line.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),i(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),i(e,{href:"https://github.com/Modrisco"},{default:n(()=>[...s[4]||(s[4]=[a("Modrisco",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=l(c,[["render",h]]);export{x as __pageData,C as default};
